// resource describes an API object type with the usual list, get, create,
// edit and delete endpoints, where items live at <collection>/<id>. The
// commands for it are generated by resourceCommands.
type resource struct {
	noun string
	// collection returns the API path of the list.
	collection func(ctx context.Context) (string, error)
	// nameKey is the field users refer to objects by; empty if objects have
	// no name and can only be referred to by ID.
	nameKey string
	columns []column
	// readOnly fields are left out when editing and kept from the original.
	readOnly []string
	// required fields must be present when creating.
	required []string

	// createFlags registers resource-specific flags on the create command
	// and returns a function that applies them to the new object.
	createFlags   func(cmd *cobra.Command) func(ctx context.Context, o api.JSONObject) error
	createExample string
	// listFlags registers filter flags on the list command and returns a
	// function giving the query to send.
	listFlags func(cmd *cobra.Command) func() (url.Values, error)
	// localFilter registers flags for filtering that the API cannot do, and
	// returns a predicate applied to the listed objects.
	localFilter func(cmd *cobra.Command) func(api.JSONObject) (bool, error)
	// self is a reference the API resolves itself, such as "me" for users.
	self string
	// defaultRef, if set, makes the argument of get optional.
	defaultRef string
}

// column is a table column of a resource list.
type column struct {
	header string
	value  func(api.JSONObject) string
	wide   bool
}

// field returns a column showing a top-level field.
func field(header, key string) column {
	return column{header: header, value: func(o api.JSONObject) string { return str(o[key]) }}
}

func wideField(header, key string) column {
	c := field(header, key)
	c.wide = true
	return c
}

// str formats a JSON value for a table cell.
func str(v any) string {
	switch v := v.(type) {
	case nil:
		return ""
	case string:
		return v
	case int64:
		return strconv.FormatInt(v, 10)
	case int:
		return strconv.Itoa(v)
	case float64:
		return strconv.FormatFloat(v, 'f', -1, 64)
	case bool:
		return strconv.FormatBool(v)
	case []any:
		parts := make([]string, len(v))
		for i, x := range v {
			parts[i] = str(x)
		}
		return strings.Join(parts, ", ")
	}
	data, _ := yaml.Marshal(v)
	return strings.TrimSpace(string(data))
}

// num returns a numeric field as int64.
func num(o api.JSONObject, key string) int64 {
	switch v := o[key].(type) {
	case int64:
		return v
	case int:
		return int64(v)
	case float64:
		return int64(v)
	case string:
		n, _ := strconv.ParseInt(v, 10, 64)
		return n
	}
	return 0
}

func (r *resource) name(o api.JSONObject) string {
	if r.nameKey == "" {
		return ""
	}
	return str(o[r.nameKey])
}

func (r *resource) label(o api.JSONObject) string {
	return r.noun + " " + quoted(r.name(o), num(o, "id"))
}

func (a *App) listResource(ctx context.Context, r *resource, query url.Values) ([]api.JSONObject, *session, string, error) {
	s, err := a.session()
	if err != nil {
		return nil, nil, "", err
	}
	path, err := r.collection(ctx)
	if err != nil {
		return nil, nil, "", err
	}
	list, err := s.Client.ListObjectsAt(ctx, withQuery(path, query))
	if err != nil {
		return nil, nil, "", err
	}
	sort.SliceStable(list, func(i, j int) bool { return num(list[i], "id") < num(list[j], "id") })
	return list, s, path, nil
}

func withQuery(path string, q url.Values) string {
	if len(q) == 0 {
		return path
	}
	return path + "?" + q.Encode()
}

// findResource resolves a reference. Numeric references are fetched
// directly; otherwise (or if there is no such ID) names are matched.
func (a *App) findResource(ctx context.Context, r *resource, ref string, exact bool) (api.JSONObject, *session, string, error) {
	s, err := a.session()
	if err != nil {
		return nil, nil, "", err
	}
	path, err := r.collection(ctx)
	if err != nil {
		return nil, nil, "", err
	}
	if r.self != "" && ref == r.self {
		o, err := s.Client.GetObjectAt(ctx, http.MethodGet, path+"/"+r.self, nil)
		return o, s, path, err
	}
	if id, err := strconv.ParseInt(ref, 10, 64); err == nil {
		o, err := s.Client.GetObjectAt(ctx, http.MethodGet, fmt.Sprintf("%s/%d", path, id), nil)
		if err == nil && o != nil {
			return o, s, path, nil
		}
		if err != nil && !api.IsStatus(err, http.StatusNotFound) && !api.IsStatus(err, http.StatusForbidden) {
			return nil, nil, "", err
		}
	}
	list, err := s.Client.ListObjectsAt(ctx, path)
	if err != nil {
		return nil, nil, "", err
	}
	o, err := resolve.Find(r.noun, ref, list, func(o api.JSONObject) resolve.Key {
		return resolve.Key{ID: num(o, "id"), Name: r.name(o)}
	}, resolve.Options{Exact: exact, NameOnly: true})
	return o, s, path, err
}

// resourceCommands returns list, get, create, edit and delete for r.
func (a *App) resourceCommands(r *resource) []*cobra.Command {
	return []*cobra.Command{
		a.newResourceListCommand(r),
		a.newResourceGetCommand(r),
		a.newResourceCreateCommand(r),
		a.newResourceEditCommand(r),
		a.newResourceDeleteCommand(r),
	}
}

func (a *App) refUse(r *resource) string {
	if r.nameKey == "" {
		return "<" + r.noun + "-id>"
	}
	return "<" + r.noun + ">"
}

func (a *App) completeResource(r *resource) completeFunc {
	return func(cmd *cobra.Command, args []string, _ string) ([]string, cobra.ShellCompDirective) {
		if len(args) > 0 {
			return nil, cobra.ShellCompDirectiveNoFileComp
		}
		list, _, _, err := a.listResource(cmd.Context(), r, nil)
		if err != nil {
			return nil, cobra.ShellCompDirectiveError
		}
		var out []string
		for _, o := range list {
			id := num(o, "id")
			desc := ""
			if len(r.columns) > 1 {
				desc = r.columns[1].value(o)
			}
			if name := r.name(o); name != "" {
				out = append(out, fmt.Sprintf("%s\tID %d", name, id))
			} else {
				out = append(out, fmt.Sprintf("%d\t%s", id, desc))
			}
		}
		return out, cobra.ShellCompDirectiveNoFileComp
	}
}

func (r *resource) rows(list []api.JSONObject) output.Rows {
	rows := output.Rows{}
	for _, c := range r.columns {
		rows.Columns = append(rows.Columns, output.Column{Header: c.header, Wide: c.wide})
	}
	for _, o := range list {
		row := make([]string, len(r.columns))
		for i, c := range r.columns {
			row[i] = c.value(o)
		}
		rows.Rows = append(rows.Rows, row)
	}
	return rows
}

func (a *App) newResourceListCommand(r *resource) *cobra.Command {
	cmd := &cobra.Command{
		Use:     "list",
		Aliases: []string{"ls"},
		Short:   fmt.Sprintf("List %ss", r.noun),
		Args:    usageArgs(cobra.NoArgs),
	}
	var query func() (url.Values, error)
	if r.listFlags != nil {
		query = r.listFlags(cmd)
	}
	var keep func(api.JSONObject) (bool, error)
	if r.localFilter != nil {
		keep = r.localFilter(cmd)
	}
	cmd.RunE = func(cmd *cobra.Command, args []string) error {
		pr, err := a.printer()
		if err != nil {
			return err
		}
		var q url.Values
		if query != nil {
			if q, err = query(); err != nil {
				return err
			}
		}
		list, _, _, err := a.listResource(cmd.Context(), r, q)
		if err != nil {
			return err
		}
		if keep != nil {
			kept := []api.JSONObject{}
			for _, o := range list {
				ok, err := keep(o)
				if err != nil {
					return err
				}
				if ok {
					kept = append(kept, o)
				}
			}
			list = kept
		}
		return pr.List(list, r.rows(list))
	}
	return cmd
}

func (a *App) newResourceGetCommand(r *resource) *cobra.Command {
	use, short, args := "get "+a.refUse(r), fmt.Sprintf("Show a %s", r.noun), cobra.ExactArgs(1)
	if r.defaultRef != "" {
		use = fmt.Sprintf("get [%s]", r.noun)
		short = fmt.Sprintf("Show a %s (default: %s)", r.noun, r.defaultRef)
		args = cobra.MaximumNArgs(1)
	}
	return &cobra.Command{
		Use:               use,
		Short:             short,
		Args:              usageArgs(args),
		ValidArgsFunction: a.completeResource(r),
		RunE: func(cmd *cobra.Command, args []string) error {
			pr, err := a.printer()
			if err != nil {
				return err
			}
			ref := r.defaultRef
			if len(args) == 1 {
				ref = args[0]
			}
			o, _, _, err := a.findResource(cmd.Context(), r, ref, false)
			if err != nil {
				return err
			}
			return printGeneric(pr, o)
		},
	}
}

// printGeneric shows an object as "key: value" lines, with nested objects
// indented one level.
func printGeneric(pr *output.Printer, o api.JSONObject) error {
	keys := make([]string, 0, len(o))
	for k := range o {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	// id and name first, as in all other details views.
	sort.SliceStable(keys, func(i, j int) bool { return rank(keys[i]) < rank(keys[j]) })
	var fields []output.Field
	for _, k := range keys {
		if m, ok := o[k].(map[string]any); ok {
			fields = append(fields, output.Field{Label: k})
			sub := make([]string, 0, len(m))
			for sk := range m {
				sub = append(sub, sk)
			}
			sort.Strings(sub)
			for _, sk := range sub {
				fields = append(fields, output.Field{Label: "  " + sk, Value: firstLine(str(m[sk]))})
			}
			continue
		}
		fields = append(fields, output.Field{Label: k, Value: firstLine(str(o[k]))})
	}
	return pr.Details(o, strconv.FormatInt(num(o, "id"), 10), fields)
}

func rank(key string) int {
	switch key {
	case "id":
		return 0
	case "name":
		return 1
	}
	return 2
}

func (a *App) newResourceCreateCommand(r *resource) *cobra.Command {
	var file string
	var fields, rawFields []string
	cmd := &cobra.Command{
		Use:   "create",
		Short: fmt.Sprintf("Create a %s", r.noun),
		Long: fmt.Sprintf(`Create a %s from flags, from a YAML or JSON file (-f), or both: flags are
applied on top of the file. Any field can be set with -F key=value (dots
create nested objects; numbers, booleans and null are typed) or with
--raw-field key=value (always a string).`, r.noun),
		Example: r.createExample,
		Args:    usageArgs(cobra.NoArgs),
	}
	var apply func(ctx context.Context, o api.JSONObject) error
	if r.createFlags != nil {
		apply = r.createFlags(cmd)
	}
	f := cmd.Flags()
	f.StringVarP(&file, "file", "f", "", `YAML or JSON file to create from ("-" for stdin)`)
	f.StringArrayVarP(&fields, "field", "F", nil, "set a field `key=value` (typed; repeatable)")
	f.StringArrayVar(&rawFields, "raw-field", nil, "set a string field `key=value` (repeatable)")
	cmd.RunE = func(cmd *cobra.Command, args []string) error {
		ctx := cmd.Context()
		pr, err := a.printer()
		if err != nil {
			return err
		}
		o := api.JSONObject{}
		if file != "" {
			data, err := a.readInput(file)
			if err != nil {
				return err
			}
			if err := yaml.Unmarshal(data, &o); err != nil {
				return usageErrorf("invalid input: %v", err)
			}
			if o == nil {
				o = api.JSONObject{}
			}
		}
		extra, err := buildFields(fields, rawFields)
		if err != nil {
			return err
		}
		mergeObjects(o, extra)
		if apply != nil {
			if err := apply(ctx, o); err != nil {
				return err
			}
		}
		for _, k := range r.required {
			if _, ok := o[k]; !ok {
				return usageErrorf("%q is required (see --help)", k)
			}
		}
		s, err := a.session()
		if err != nil {
			return err
		}
		path, err := r.collection(ctx)
		if err != nil {
			return err
		}
		created, err := s.Client.GetObjectAt(ctx, http.MethodPost, path, o)
		if err != nil {
			return err
		}
		if created == nil {
			// Some endpoints do not return the new object.
			a.info("Created %s.", r.noun)
			return nil
		}
		a.info("Created %s.", r.label(created))
		return printGeneric(pr, created)
	}
	return cmd
}

// mergeObjects copies src into dst, merging nested objects.
func mergeObjects(dst, src map[string]any) {
	for k, v := range src {
		sm, sok := v.(map[string]any)
		dm, dok := dst[k].(map[string]any)
		if sok && dok {
			mergeObjects(dm, sm)
			continue
		}
		dst[k] = v
	}
}

func (a *App) newResourceEditCommand(r *resource) *cobra.Command {
	return &cobra.Command{
		Use:   "edit " + a.refUse(r),
		Short: fmt.Sprintf("Edit a %s in your editor", r.noun),
		Long: `Open the object as YAML in $VISUAL or $EDITOR (default: vi, or notepad on
Windows). When you save and close the editor, the changes are sent to the
server. If the server rejects them, the editor opens again with the error.
Save without changes to cancel.`,
		Args:              usageArgs(cobra.ExactArgs(1)),
		ValidArgsFunction: a.completeResource(r),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			o, s, path, err := a.findResource(ctx, r, args[0], false)
			if err != nil {
				return err
			}
			return a.editGeneric(ctx, s, r.label(o), o, r.readOnly, fmt.Sprintf("%s/%d", path, num(o, "id")))
		},
	}
}

// editGeneric edits o in the editor and PUTs the result to path. readOnly
// fields are not shown and are sent unchanged.
func (a *App) editGeneric(ctx context.Context, s *session, label string, o api.JSONObject, readOnly []string, path string) error {
	editable := api.JSONObject{}
	var fixed []string
	for k, v := range o {
		if slices.Contains(readOnly, k) {
			fixed = append(fixed, fmt.Sprintf("%s %s", k, str(v)))
			continue
		}
		editable[k] = v
	}
	sort.Strings(fixed)
	body, err := yaml.Marshal(editable)
	if err != nil {
		return err
	}
	header := fmt.Sprintf("Editing %s.\n", label)
	if len(fixed) > 0 {
		header += "Read-only: " + strings.Join(fixed, ", ") + ".\n"
	}
	header += "Save without changes to cancel."
	err = a.editLoop(header, body, func(data []byte) error {
		edited := api.JSONObject{}
		if err := yaml.Unmarshal(data, &edited); err != nil {
			return fmt.Errorf("invalid YAML: %w", err)
		}
		for _, k := range readOnly {
			if v, ok := o[k]; ok {
				edited[k] = v
			}
		}
		_, err := s.Client.CallJSON(ctx, http.MethodPut, path, edited)
		return err
	})
	if errors.Is(err, errEditCancelled) {
		a.info("No changes made.")
		return nil
	}
	if err != nil {
		return err
	}
	a.info("Updated %s.", label)
	return nil
}

func (a *App) newResourceDeleteCommand(r *resource) *cobra.Command {
	var yes bool
	short := fmt.Sprintf("Delete a %s (ID or exact name required)", r.noun)
	if r.nameKey == "" {
		short = fmt.Sprintf("Delete a %s", r.noun)
	}
	cmd := &cobra.Command{
		Use:               "delete " + a.refUse(r),
		Aliases:           []string{"rm"},
		Short:             short,
		Args:              usageArgs(cobra.ExactArgs(1)),
		ValidArgsFunction: a.completeResource(r),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			o, s, path, err := a.findResource(ctx, r, args[0], true)
			if err != nil {
				return err
			}
			if err := a.confirm(fmt.Sprintf("Delete %s?", r.label(o)), yes); err != nil {
				return err
			}
			if _, err := s.Client.CallJSON(ctx, http.MethodDelete, fmt.Sprintf("%s/%d", path, num(o, "id")), nil); err != nil {
				return err
			}
			a.info("Deleted %s.", r.label(o))
			return nil
		},
	}
	cmd.Flags().BoolVarP(&yes, "yes", "y", false, "do not ask for confirmation")
	return cmd
}

// installationPath returns a collection function for a path below the
// current installation, e.g. "/api/v2/schedule/%d".
func (a *App) installationPath(format string) func(ctx context.Context) (string, error) {
	return func(ctx context.Context) (string, error) {
		sc, err := a.scope(ctx)
		if err != nil {
			return "", err
		}
		return fmt.Sprintf(format, sc.installation), nil
	}
}
